_SPLIT_CACHE = {}


def detect_format(activation_dir):
    p = Path(activation_dir)
    if list(p.glob("L*/en_train.npy")):
        return "npy"
    if list(p.glob("layer*_en_train.pt")):
        return "pt_split"
    if list(p.glob("layer*_en.pt")):
        return "pt_flat"
    raise FileNotFoundError(f"No activations found in {activation_dir}")


def discover_layers(activation_dir, fmt):
    p = Path(activation_dir)
    if fmt == "npy":
        return sorted(int(d.name[1:]) for d in p.glob("L*")
                       if (d / "en_train.npy").exists())
    elif fmt == "pt_split":
        return sorted({int(f.stem.split("_")[0].replace("layer", ""))
                       for f in p.glob("layer*_en_train.pt")})
    else:
        return sorted({int(f.stem.split("_")[0].replace("layer", ""))
                       for f in p.glob("layer*_en.pt")})


def discover_languages(activation_dir, fmt, layers):
    p = Path(activation_dir)
    langs = set()
    for layer in layers:
        if fmt == "npy":
